// Package gmptest holds the fixture corpus and protocol-fidelity tooling that
// checks the command structs in commands/ against real GMP documents.
//
// It is internal: the registry below is a maintenance artifact, not API, and
// T-9's codegen is expected to replace it.
package gmptest

import "github.com/brennoo/go-gmp/commands"

// Command binds a GMP command name to constructors for its request and
// response types. Fixtures are stored per command name, and nothing in Go can
// map "get_tasks" to commands.GetTasks without a table like this one.
type Command struct {
	Name    string
	NewReq  func() any
	NewResp func() any
}

// Registry covers every root command: a request type whose XMLName tag has a
